import { readdir, readFile, writeFile } from 'node:fs/promises';
import { relative, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const folders = ['evals', 'patterns', 'references', 'rulesets'];
const files = ['ACCESSIBILITY.md', 'CHANGELOG.md', 'HANDOFF.md', 'PROMPT.md', 'README.md', 'SKILL.md', 'TUTORIAL.md'];

for (const folder of folders) {
  const directory = resolve(root, folder);
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    if (entry.isFile() && entry.name.endsWith('.md')) {
      files.push(relative(root, resolve(directory, entry.name)).replaceAll('\\', '/'));
    }
  }
}

// One generated transfer artifact for clipboard, download and offline fallback.
const packageFiles = ['PROMPT.md', 'ACCESSIBILITY.md', 'SKILL.md'];
for (const folder of folders) {
  for (const entry of (await readdir(resolve(root, folder), { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name, 'en'))) {
    if (entry.isFile() && /\.(md|json)$/.test(entry.name)) packageFiles.push(`${folder}/${entry.name}`);
  }
}
function createStartKit(documents, packageFiles) {
  const sections = packageFiles.map(file => `## Datei: ${file}\n\n${documents[file].trim()}\n\n## Ende Datei: ${file}`);
  return `# a11y-copilot – vollständiges Startpaket\n\nDieses Textpaket übergibt Wissen an einen KI-Chat. Es stellt keine Verbindung zur Website her und führt keine Tests aus. Die folgenden Dateinamen kennzeichnen enthaltene Abschnitte, keine separat angelegten Dateien. Externe Quellen und das zu untersuchende Projekt sind nicht enthalten.\n\nEnthaltene Abschnitte:\n${packageFiles.map(file => `- ${file}`).join('\n')}\n\n---\n\n${sections.join('\n\n---\n\n')}\n\nEnde des vollständigen Startpakets.\n`;
}

const documentFiles = [...new Set([...files, ...packageFiles])].sort();
const documents = Object.fromEntries(
  await Promise.all(documentFiles.map(async file => [file, await readFile(resolve(root, file), 'utf8')]))
);
await writeFile(resolve(root, 'STARTPAKET.txt'), createStartKit(documents, packageFiles));
// Compose the fallback on demand from the same sources without storing them twice.
const output = `/* Generated by scripts/build-markdown-bundle.mjs. Do not edit directly. */\nwindow.A11Y_MARKDOWN_CONTENT = ${JSON.stringify(documents)};\nObject.defineProperty(window.A11Y_MARKDOWN_CONTENT, "STARTPAKET.txt", { enumerable: true, get: () => (${createStartKit.toString()})(window.A11Y_MARKDOWN_CONTENT, ${JSON.stringify(packageFiles)}) });\n`;
await writeFile(resolve(root, 'assets/markdown-content.js'), output);
console.log(`Bundled ${documentFiles.length} source documents and start kit.`);
